WITH recent_stores AS (SELECT *, CASE WHEN city IN ('Berlin', 'Chiang Mai') THEN 'Group A' ELSE 'Other' END AS city_group FROM stores WHERE opened_date <= '2024-01-27' AND sqft IS NOT NULL AND sqft = 5975), stores_stats AS (SELECT YEAR(opened_date) AS opened_year, MAX(sqft) AS max_sqft FROM recent_stores GROUP BY YEAR(opened_date)) SELECT opened_year, max_sqft FROM stores_stats WHERE max_sqft < 6000 ORDER BY max_sqft DESC, opened_year DESC LIMIT 3
